  banded_sidewalk: { name: 'Marche latérale avec élastique', cues: 'Élastique aux genoux, reste bas, pas chassés en continu.' },
  hip_thrust: { name: 'Hip thrust', cues: 'Menton rentré, extension complète, serre les fessiers.' },
